CREATE TABLE IF NOT EXISTS public."type" (
  "typeId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.menu (
  "menuId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  price NUMERIC(10, 2) NOT NULL CHECK (price >= 0),
  "isBestSeller" BOOLEAN NOT NULL DEFAULT FALSE,
  "typeId" INTEGER NOT NULL REFERENCES public."type" ("typeId")
    ON UPDATE CASCADE
    ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_menu_type_id ON public.menu ("typeId");

CREATE TABLE IF NOT EXISTS public.users (
  "userId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "userName" VARCHAR(50) NOT NULL UNIQUE,
  email VARCHAR(255) NOT NULL UNIQUE,
  password VARCHAR(100) NOT NULL,
  role VARCHAR(10) NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin'))
);

CREATE TABLE IF NOT EXISTS public.rating (
  "userId" INTEGER NOT NULL REFERENCES public.users ("userId") ON DELETE CASCADE,
  "menuId" INTEGER NOT NULL REFERENCES public.menu ("menuId") ON DELETE CASCADE,
  score SMALLINT NOT NULL CHECK (score BETWEEN 1 AND 5),
  PRIMARY KEY ("userId", "menuId")
);

CREATE INDEX IF NOT EXISTS idx_rating_menu_id ON public.rating ("menuId");
